  KEY `router_path` (`router_path`(128))
) ENGINE=InnoDB AUTO_INCREMENT=4414 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='Contains the individual links within a menu.';
